def private_sum_capped(data, epsilon, rng):
    if not data:
        return 0.0

    clipped_data = np.clip(data, 0, 30)

    clip_count = rng.binomial(len(clipped_data), 1 - math.exp(-epsilon / len(clipped_data)))
    clip_indices = rng.choice(range(len(clipped_data)), clip_count)
    clipped_data[clip_indices] = 0

    return np.sum(clipped_data)

